{
  "summary": {
    "value": "Effy confirme un accès frauduleux via les identifiants d’un artisan exposant des données personnelles et projets de rénovation de clients.",
    "confidence": 0.9,
    "evidence": "Effy, spécialiste français de la rénovation énergétique, confirme un incident de sécurité ayant permis à un tiers non autorisé d’accéder aux informations personnelles de certains de ses clients."
  },
  "incident_summary": [
    {
      "value": "Un individu non autorisé a utilisé les identifiants de la société Airtech pour accéder à l'espace professionnel Effy Pro et consulter des dossiers clients.",
      "confidence": 0.95,
      "evidence": "Dans sa notification,  Effy confirme qu’un individu non autorisé a utilisé les identifiants de connexion de la société Airtech  pour accéder à son espace professionnel Effy Pro."
    },
    {
      "value": "Les données accessibles incluent noms, adresses, adresses des chantiers, numéros de téléphone, emails, nature des travaux et créneaux de disponibilité.",
      "confidence": 0.95,
      "evidence": "Selon Effy, les données concernées comprennent : Civilités, noms et prénoms  des particuliers ; Adresses personnelles  ; Adresses précises des chantiers  ; Numéros de téléphone ; Adresses email ;  Nature des travaux envisagés  ;  Créneaux pendant lesquels les particuliers sont joignables ."
    }
  ],
  "activity_description": {
    "value": "Effy, spécialiste français de la rénovation énergétique, accompagne les particuliers dans leurs projets d'isolation, de chauffage et d'installation de pompes à chaleur et met en relation avec des artisans qualifiés.",
    "confidence": 0.9,
    "evidence": "Fondé en 2008, Effy est un groupe français spécialisé dans l’accompagnement des travaux de rénovation énergétique.  Basé à Paris, il aide les particuliers à réaliser leurs projets d’isolation, de chauffage ou d’installation de pompes à chaleur, notamment en les mettant en relation avec des artisans qualifiés."
  },
  "activity_sector_match": {
    "value": "Énergie / Utilities",
    "confidence": 0.9,
    "evidence": "Fondé en 2008, Effy est un groupe français spécialisé dans l’accompagnement des travaux de rénovation énergétique.  Basé à Paris, il aide les particuliers à réaliser leurs projets d’isolation, de chauffage ou d’installation de pompes à chaleur, notamment en les mettant en relation avec des artisans qualifiés."
  },
  "threat_candidate": {
    "value": "Malware",
    "confidence": 0.75,
    "evidence": "Les identifiants de la société Airtech auraient vraisemblablement été récupérés sur Internet, après le piratage de l’ordinateur d’un professionnel ou l’installation d’un logiciel espion."
  }
}

